class Solution {
public:
    bool hasMatch(string s, string p) {
        int starIdx = p.find('*');
        string prefix = p.substr(0, starIdx);
        string suffix = p.substr(starIdx + 1);

        int i = s.find(prefix);
        if (i == string::npos) return false;

        int j = s.find(suffix, i + prefix.length());
        return j != string::npos;
    }
};

class Solution {
    public boolean hasMatch(String s, String p) {
        int starIdx = p.indexOf('*');
        String prefix = p.substring(0, starIdx);
        String suffix = p.substring(starIdx + 1);

        int i = s.indexOf(prefix);
        if (i == -1) return false;

        int j = s.indexOf(suffix, i + prefix.length());
        return j != -1;
    }
}

var hasMatch = function(s, p) {
    const starIdx = p.indexOf('*');
    const prefix = p.slice(0, starIdx);
    const suffix = p.slice(starIdx + 1);

    const i = s.indexOf(prefix);
    if (i === -1) return false;

    const j = s.indexOf(suffix, i + prefix.length);
    return j !== -1;
};
